#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/git/tasks/git-worktree-create.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Create a worktree for a branch, and set it up"
# MISE tools={uv="latest", python="3.14"}
# USAGE arg "<branch>" help="the branch of the worktree; a branch that does not exist is created"
# USAGE flag "--from <base>" help="the base of a new branch; the default is the default branch"
# USAGE flag "--current" help="cut a new branch from the current branch, not from the default branch"
# USAGE flag "--no-setup" help="skip git:worktree:setup in the new worktree; mise trust still runs"

# The worktree is in `.worktrees/<branch>` of the main checkout, or in
# `worktrees/<branch>` when only `worktrees/` exists. A branch that exists
# here is checked out. A branch only on origin becomes a local branch that
# tracks it. Each other branch is new, cut from --from, from the current branch
# with --current, else from the default branch (default_branch of
# `.config/bootstrap/repo.toml`): the local branch when it exists, else the
# branch of origin.
# A core branch (core_branches of `.config/bootstrap/repo.toml`) never gets a
# worktree of this task: the merges check it out in the main checkout.

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import checks  # noqa: E402
import helpers  # noqa: E402

# mise sets the `usage_*` variables from the `# USAGE` lines above.
BRANCH = os.environ.get("usage_branch", "")
FROM = os.environ.get("usage_from", "")
CURRENT = os.environ.get("usage_current") == "true"
NO_SETUP = os.environ.get("usage_no_setup") or "false"

helpers.print_header(f"Creating the worktree of {BRANCH} ...")

if FROM and CURRENT:
  helpers.print_error("use --from or --current, not both.")
  sys.exit(2)

core_value = helpers.core_branches()
if BRANCH in [str(core) for core in core_value]:
  helpers.print_error(f"'{BRANCH}' is a core branch, and a core branch gets no worktree.")
  sys.exit(2)

MAIN_WORKTREE_PATH = checks.get_main_worktree_path()
DIR = ".worktrees"
if not os.path.exists(f"{MAIN_WORKTREE_PATH}/.worktrees") and os.path.isdir(f"{MAIN_WORKTREE_PATH}/worktrees"):
  DIR = "worktrees"
WORKTREE = f"{MAIN_WORKTREE_PATH}/{DIR}/{BRANCH}"

if os.path.exists(WORKTREE):
  helpers.print_error(f"{WORKTREE} already exists.")
  sys.exit(1)


def require_no_from(where=""):
  """Stops the task: --from and --current are a usage error for a branch that
  exists."""
  if FROM or CURRENT:
    suffix = f" on {where}" if where else ""
    flag = "--from" if FROM else "--current"
    helpers.print_error(f"{flag} is for a new branch, and '{BRANCH}' exists{suffix}.")
    sys.exit(2)


def ref_exists(ref):
  """Whether git has the ref."""
  return subprocess.run(["git", "show-ref", "--verify", "--quiet", ref], check=False).returncode == 0


FROM_ORIGIN = False

if ref_exists(f"refs/heads/{BRANCH}"):
  require_no_from()
  ADD = [WORKTREE, BRANCH]
  KIND = f"the branch {BRANCH}"
elif ref_exists(f"refs/remotes/origin/{BRANCH}"):
  require_no_from("origin")
  ADD = ["--track", "-b", BRANCH, WORKTREE, f"origin/{BRANCH}"]
  KIND = f"a local branch {BRANCH} that tracks origin/{BRANCH}"
  FROM_ORIGIN = True
elif FROM:
  ADD = ["-b", BRANCH, WORKTREE, FROM]
  KIND = f"the new branch {BRANCH} from {FROM}"
elif CURRENT:
  ADD = ["-b", BRANCH, WORKTREE, "HEAD"]
  KIND = f"the new branch {BRANCH} from the current branch"
else:
  BASE = helpers.default_branch()
  if not ref_exists(f"refs/heads/{BASE}") and ref_exists(f"refs/remotes/origin/{BASE}"):
    BASE = f"origin/{BASE}"
  # --no-track: a branch cut from origin/<base> must not push to <base>.
  ADD = ["--no-track", "-b", BRANCH, WORKTREE, BASE]
  KIND = f"the new branch {BRANCH} from the default branch {BASE}"

# git refuses a branch that another worktree has checked out, and says so.
helpers.print_info(f"Adding {WORKTREE} on {KIND}")
if subprocess.run(["git", "worktree", "add", "--quiet", *ADD], check=False).returncode != 0:
  helpers.print_error("git worktree add failed.")
  sys.exit(1)
helpers.print_success(f"Added {WORKTREE}")


def keep_worktree(message):
  """Stops the task after the add. The worktree stays, and the output gives the
  commands that complete it or undo it."""
  helpers.print_error(message)
  helpers.print_warn(f"- the worktree stays at {WORKTREE}")
  helpers.print_warn(f"- set it up again: `mise run --cd {WORKTREE} git:worktree:setup`")
  helpers.print_warn(f"- or delete it: `mise run git:worktree:delete {BRANCH}`")
  sys.exit(1)


# A branch only on origin can hold a mise config or a setup task that a
# different person pushed: trust and setup run it as it is, with no review step.
if FROM_ORIGIN:
  helpers.print_warn(f"The mise config of the worktree comes from origin/{BRANCH}, and it is trusted and run as is.")
helpers.print_wait("Trusting the mise config of the worktree ... ")
trust = subprocess.run(
  ["mise", "trust"], check=False, cwd=WORKTREE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True
)
if trust.returncode != 0:
  helpers.print_error()
  sys.stderr.write(f"{trust.stdout.rstrip(chr(10))}\n")
  sys.stderr.flush()
  keep_worktree(f"mise trust failed in {WORKTREE}.")
helpers.print_success()

if NO_SETUP == "true":
  helpers.print_info("Skipping git:worktree:setup (--no-setup)")
elif subprocess.run(["mise", "run", "--cd", WORKTREE, "git:worktree:setup"], check=False).returncode != 0:
  keep_worktree(f"git:worktree:setup failed in {WORKTREE}.")

helpers.print_newline()
helpers.print_success(f"The worktree of {BRANCH} is ready at {WORKTREE}")
